 close=json.loads((HERE/'CLOSE_RESULT90.json').read_text());proof=next(r for r in close['frames']if r['frame']==140);assert proof['robustDecision']['winner']==0 and proof['robustDecision']['massBounds']['4'][1]==0
 old=ROOT/'native-feature89';path=old/'final-input89/0140-ray-visible.bin';r=Reader(path);assert r.s()=='final-palette89/v1';sid,variant=r.s(),r.s();frame,serial,w,h,count=[r.i()for _ in range(5)];base=r.a(w*h*4).reshape(h,w,4);selected=r.a(w*h*4).reshape(h,w,4);palette=r.a(count*4).reshape(count,4);r.end();original=selected.copy();fixed=selected.copy();manifest=json.loads(sorted((old/'capture89f').glob('STATE89*.json'))[-1].read_text());d=packet(Path(next(e['output']for e in manifest['sequencePackets']if e['frame']==frame)));m=d['m'];yy,xx=np.mgrid[:h,:w];p=(np.stack([xx+m['nativeFinalReference89']['nativeROI'][0]+.5,yy+m['nativeFinalReference89']['nativeROI'][1]+.5],-1)-np.asarray(m['nativeFinalReference89']['origin']))/m['nativeFinalReference89']['scale']-np.asarray(m['trace86']['headJoinOffset'])-np.asarray(m['camera86']['deliveredDelta'][:2]);top=p.copy();top[...,1]=272-p[...,1];local=np.floor(top-np.asarray(m['retarget89']['anchor'])).astype(int);target=(local[...,0]==5)&(local[...,1]==0)&(selected[...,0]>0)&(selected[...,1]==4);assert target.sum()==4;rx,ry,rw,rh=d['roi'];evidence=[]
 for y,x in np.argwhere(target):
  cx,cy=np.floor(p[y,x]).astype(int);i,j=cy-ry,cx-rx;meta=d['a']['base-meta'][i,j];decoded=decode_independent_meta(meta);oldOwner=d['a']['old-eye-owner'][i,j];intrinsic=d['a']['old-intrinsic'][i,j];assert decoded and decoded['role']==3 and decoded['alpha']==1;assert intrinsic[0]==0 and oldOwner[0]!=2 and oldOwner[0]!=7
  evidence.append({'nativeROIbottomLeft':[int(x),int(y)],'headCellTopLeft':[int(cx),int(271-cy)],'baseDecoded':decoded,'oldEyeOwnerTags':oldOwner.tolist(),'oldIntrinsic':intrinsic.tolist(),'originalNativeRGB8':rgb8(base[y,x,:3]).tolist(),'originalNativeOwnerTags':d['a']['native-final-owner'][y,x].tolist(),'originalNativeDepthAudit':d['a']['native-final-depth'][y,x].tolist(),'retentionReason':'No displaced authored eye at destination; existing actual source skin is available. Keep baseline when the new candidate is physically occluded.'})
 fixed[target]=0;assert np.array_equal(fixed[~target],original[~target]);out=HERE/'focus-input90';out.mkdir(exist_ok=False)
 with(out/'0140-focused90.bin').open('xb')as f:
  string(f,'final-palette89/v1');string(f,sid);string(f,'focused90');f.write(struct.pack('<5i',frame,serial,w,h,count));f.write(base.astype('<f4').tobytes());f.write(fixed.astype('<f4').tobytes());f.write(palette.astype('<f4').tobytes())
 oldColour=base.copy();mask=original[...,0]>0;oldColour[mask]=palette[original[...,0][mask].astype(int)-1];newColour=base.copy();mask=fixed[...,0]>0;newColour[mask]=palette[fixed[...,0][mask].astype(int)-1];assert np.array_equal(newColour[target],base[target]);assert np.array_equal(newColour[~target],oldColour[~target]);assert(rgb8(oldColour[target,:3])==255).all();assert(rgb8(newColour[target,:3])==[183,127,113]).all();np.savez_compressed(HERE/'FOCUS_EXPECTED90.npz',colour=newColour,owner=fixed,oldColour=oldColour,baseline=base,target=target,palette=palette)
 report={'status':'FOCUSED_GHOST_SELECTOR_FIX_PREPARED_NOT_PRODUCT_APPLIED','sourceId':sid,'frame':frame,'serial':serial,'newCapture':False,'sourceCellAbsolute':[5,0],'nativePixels':evidence,'selectionChange':'Only confirmed occluded new-white selector is removed. Existing actual skin baseline retained; no RGB is synthesized.','otherSelectionFieldsUnchanged':True,'ownerDepthRetention':'Original native owner/depth remain the pass-through source; new selector metadata0 means preserve, not an invented owner.','unresolvedOther89CellsRetained':True};(HERE/'FOCUS_INPUT90.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'pixels':len(evidence),'oldRGB8':[255,255,255],'retainedActualRGB8':[183,127,113],'outsideTargetChanged':0},indent=2))
